Save sandbox.pkr.hcl, a small template in the shape of packer/packer/packer.pkr.hcl, amazon-ebs only:

packer {
  required_plugins {
    amazon  = { source = "github.com/hashicorp/amazon", version = "~> 1" }
    ansible = { source = "github.com/hashicorp/ansible", version = "~> 1" }
  }
}

variable "image_name" { type = string }
variable "channel" {
  type = string
  validation {
    condition     = contains(["testing", "release"], var.channel)
    error_message = "The channel is testing or release."
  }
}
variable "instance_type" { type = string }
variable "volume_size" { type = number }

source "amazon-ebs" "sandbox" {
  region        = "us-east-1"
  ami_name      = "rhino-${var.image_name}-v1-${var.channel}-${formatdate("YYYYMMDDhhmm", timestamp())}"
  instance_type = var.instance_type
  ssh_username  = "ubuntu"
  source_ami_filter {
    owners      = ["self"]
    most_recent = true
    filters     = { name = "rhino-base-ubuntu-24-v1-release-*" }
  }
  launch_block_device_mappings {
    device_name           = "/dev/sda1"
    volume_size           = var.volume_size
    volume_type           = "gp3"
    delete_on_termination = true
  }
  tags = { channel = var.channel, image = var.image_name }
}

build {
  sources = ["source.amazon-ebs.sandbox"]
  provisioner "ansible" {
    playbook_file = "./playbook.yml"
    user          = "ubuntu"
  }
}
